// Gera N mensagens fictícias de alunos da Flowgrammers, cada uma com GABARITO.
// Determinístico: mesma semente, mesmo dataset. Assim a comparação é justa entre modelos e entre execuções.
const cfg = $('Configuração').first().json;
const N = Math.max(1, Math.min(5000, Number(cfg.registros) || 200));
let seed = (Number(cfg.semente) || 2026) >>> 0;
const rnd = () => {                                   // mulberry32
  seed = (seed + 0x6D2B79F5) >>> 0;
  let t = seed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const pick = arr => arr[Math.floor(rnd() * arr.length)];

const PRODUTOS = ['n8n Expert Program', 'Claude Code Engineering', 'Harness Engineering', 'Fábrica de SaaS ao Vivo'];
const CANAIS = ['whatsapp', 'comunidade', 'email'];
const ABERTURAS = ['Oi!', 'Bom dia, pessoal.', 'Boa tarde!', 'Oi, time.', 'Pessoal,', ''];
const FECHOS = ['Alguém consegue dar uma olhada?', 'Já tentei de novo e nada.', 'Consegue me ajudar?', 'Valeu!', ''];
const FECHOS_CRITICOS = ['Tá em produção, preciso de ajuda hoje.', 'O cliente já ligou duas vezes.', 'Tô com o cliente parado esperando.'];
const FRUSTRACAO = [
  'É a terceira vez que isso acontece. Tô pensando em pedir reembolso.',
  'Se não resolver essa semana eu vou cancelar.',
  'Paguei à vista e tô bem frustrado, quero meu dinheiro de volta.',
  'Sinceramente, tô quase desistindo do curso.'
];
const RESPOSTAS_SUPORTE = ['Oi! Vamos verificar e já te retornamos.', 'Recebido, estamos olhando.', 'Consegue mandar um print do erro?'];
const FOLLOW_UPS = ['Alguma novidade?', 'Mandei o print aí.', 'Continua igual por aqui.'];

// u = urgência de 0 (nenhuma) a 4 (crítica) · compra = sinal consistente de intenção de compra
const CATALOGO = {
  suporte_tecnico: [
    { u: 4, t: 'O workflow de cobrança do meu cliente parou depois da atualização do n8n e o HTTP Request agora volta 401.' },
    { u: 4, t: 'Meu agente de atendimento em produção começou a responder errado pros clientes desde ontem.' },
    { u: 4, t: 'O n8n do cliente caiu e a fila do Redis não volta de jeito nenhum.' },
    { u: 4, t: 'O webhook de pagamento parou de receber eventos e o cliente tá perdendo venda.' },
    { u: 3, t: 'O Claude Code trava no hook PreToolUse e não executa mais nenhum comando.' },
    { u: 3, t: 'O deploy do Docker Swarm do módulo 6 falha no healthcheck e não sei sair disso.' },
    { u: 3, t: 'O nó do Postgres dá timeout em toda execução do exercício 3.' },
    { u: 3, t: 'Meu MCP server não aparece no Claude Code depois de configurar o settings.json.' },
    { u: 2, t: 'O Code node retorna undefined quando uso $input.all() dentro do loop.' },
    { u: 2, t: 'O Switch manda tudo pro fallback mesmo com a regra certa.' },
    { u: 2, t: 'O agente responde em inglês mesmo com o system prompt em português.' },
    { u: 2, t: 'O Merge junta os itens fora de ordem no meu fluxo de pedidos.' },
    { u: 1, t: 'Apareceu um aviso de nó deprecated no HTTP Request, preciso me preocupar?' },
    { u: 1, t: 'O editor do n8n fica lento quando o workflow passa de 80 nós.' }
  ],
  acesso_plataforma: [
    { u: 1, t: 'Terminei o módulo 4 e o certificado não aparece na minha área.' },
    { u: 3, t: 'Não consigo entrar na plataforma, o link de login expira na hora.' },
    { u: 2, t: 'A aula 7 do módulo de agentes está com o vídeo travado em 0:00.' },
    { u: 3, t: 'Comprei o curso ontem e ainda não liberou o acesso.' },
    { u: 2, t: 'A live de hoje caiu no meio e não achei a gravação.' },
    { u: 3, t: 'Troquei de e-mail e perdi o acesso aos cursos.' },
    { u: 1, t: 'O player não carrega no celular, só no computador.' },
    { u: 1, t: 'O material de apoio da aula 3 dá erro 404.' }
  ],
  comercial: [
    { u: 1, compra: true, t: 'Coordeno o time de automação de uma seguradora e queremos uma turma fechada de Claude Code pra 15 analistas.' },
    { u: 1, compra: true, t: 'Quero fazer o upgrade pro Harness Engineering, como faço o pagamento?' },
    { u: 1, compra: true, t: 'Vocês emitem nota fiscal pra empresa? Quero comprar 3 acessos do n8n Expert Program.' },
    { u: 1, compra: true, t: 'Tem desconto pra quem já é aluno? Se tiver eu fecho o Claude Code Engineering hoje.' },
    { u: 1, compra: true, t: 'Qual o próximo lote da Fábrica de SaaS ao Vivo? Quero garantir minha vaga.' },
    { u: 0, compra: false, t: 'Quanto custa?' },
    { u: 0, compra: false, t: 'Vocês parcelam?' }
  ],
  conteudo: [
    { u: 0, t: 'Sugestão: uma aula sobre como versionar workflows do n8n com Git.' },
    { u: 0, t: 'Adorei a aula de Harness Engineering, dá pra ter uma parte 2 sobre avaliação de agentes?' },
    { u: 0, t: 'Qual a diferença conceitual entre o AI Agent do n8n e um agente no Claude Code?' },
    { u: 0, t: 'A explicação de RAG no módulo 5 ficou confusa pra mim, podiam refazer com um exemplo?' },
    { u: 0, t: 'Faltou falar de custo de tokens na aula de agentes.' },
    { u: 0, t: 'Vocês recomendam algum livro sobre arquitetura de agentes?' }
  ],
  indefinido: [
    { u: 0, t: 'oi, tudo bem?' }, { u: 0, t: 'bom dia' }, { u: 0, t: 'alguém aí?' },
    { u: 0, t: 'ok' }, { u: 0, t: 'obrigado!' }, { u: 0, t: '👍' }
  ]
};
const PESOS = [['suporte_tecnico', 0.30], ['acesso_plataforma', 0.25], ['comercial', 0.18], ['conteudo', 0.15], ['indefinido', 0.12]];
const sorteiaRota = () => {
  const r = rnd(); let acc = 0;
  for (const [rota, peso] of PESOS) { acc += peso; if (r < acc) return rota; }
  return 'indefinido';
};

const out = [];
for (let i = 0; i < N; i++) {
  const rota = sorteiaRota();
  const base = pick(CATALOGO[rota]);
  let urgencia = base.u, evasao = false;
  let texto = rota === 'indefinido'
    ? base.t
    : [pick(ABERTURAS), base.t, pick(base.u >= 4 ? FECHOS_CRITICOS : FECHOS)].filter(Boolean).join(' ');
  if ((rota === 'suporte_tecnico' || rota === 'acesso_plataforma') && rnd() < 0.18) {
    texto += ' ' + pick(FRUSTRACAO);
    evasao = true;
    urgencia = Math.max(urgencia, 2);
  }
  const mensagens = [{ de: 'aluno', texto }];
  if (rota !== 'indefinido' && rnd() < 0.25) {
    mensagens.push({ de: 'suporte', texto: pick(RESPOSTAS_SUPORTE) }, { de: 'aluno', texto: pick(FOLLOW_UPS) });
  }
  const lead = rota === 'comercial' && rnd() < 0.4;
  out.push({ json: {
    id: 'msg_' + String(i + 1).padStart(4, '0'),
    canal: pick(CANAIS),
    produto: lead ? null : pick(PRODUTOS),
    aluno_desde: lead ? null : '2026-' + String(1 + Math.floor(rnd() * 9)).padStart(2, '0'),
    mensagens,
    gabarito: { rota, urgencia, evasao, compra: !!base.compra }
  }});
}
return out;

// Monta a requisição de cada mensagem do lote e marca o início do relógio.
