  comercial: 'Quer comprar, fazer upgrade, turma para empresa, preço ou proposta',
  conteudo: 'Sugestão de aula, feedback sobre conteúdo ou dúvida conceitual sem erro concreto',
  indefinido: 'A conversa não traz informação suficiente para decidir a fila'
};
const URGENCIA = [
  'Nenhuma: cumprimento, elogio ou sugestão',
