  const cod = m ? Number(m[1]) : (e?.httpCode ? Number(e.httpCode) : null);
  return cod ? `HTTP ${cod}${DICAS[cod] ? ' · ' + DICAS[cod] : ''}` : String(e?.message ?? e).slice(0, 120);
};
