  const rota = a.rota ?? {};
  const p = rota.probabilities ?? {};
  // contrato do Choice: escolha válida, probabilidades somando ~1 e a escolha sendo a mais provável
  const somaOk = Math.abs(Object.values(p).reduce((x, y) => x + y, 0) - 1) <= 0.02;
  if (!ROTAS_IDS.includes(rota.choice) || !somaOk || p[rota.choice] < Math.max(...Object.values(p)) - 1e-6) return null;
  return { rota: rota.choice, urgencia: a.urgencia?.score, risco_churn: a.risco_churn?.noul, intencao_compra: a.intencao_compra?.noul };
})(); } catch (e) { partes = null; }
const r = resultado(res, rec, partes);
