r.tokens_estimados = !(res.usage && (res.usage.input_tokens ?? res.usage.prompt_tokens) != null);
r.t0 = rec._t0_jev;
r.t1 = t1;
r.tokens_entrada = r.erro && res.error ? 0 : (res.usage?.input_tokens ?? res.usage?.prompt_tokens ?? Math.ceil(JSON.stringify(req).length / 4));
r.tokens_saida = r.erro && res.error ? 0 : (res.usage?.output_tokens ?? res.usage?.completion_tokens ?? 0);
delete rec._req_jev;
delete rec._t0_jev;
return { json: { ...rec, jev: r } };

