    rota: ok ? partes.rota : null,
    urgencia: ok ? partes.urgencia : null,
    risco_churn: ok ? partes.risco_churn : null,
    intencao_compra: ok ? partes.intencao_compra : null,
    erro: ok ? null : (res.error ? erroHttp(res.error) : 'resposta fora do contrato')
  };
};

const rec = { ...$('⏱ GPT início').item.json };
const req = rec._req_gpt;
const res = $json;
let partes = null;
try { partes = JSON.parse(res.choices?.[0]?.message?.content ?? 'null'); } catch (e) { partes = null; }
const r = resultado(res, rec, partes);
r.t0 = rec._t0_gpt;
r.t1 = t1;
r.tokens_entrada = r.erro && res.error ? 0 : (res.usage?.prompt_tokens ?? 0);
r.tokens_saida = r.erro && res.error ? 0 : (res.usage?.completion_tokens ?? 0);
delete rec._req_gpt;
delete rec._t0_gpt;
return { json: { ...rec, gpt: r } };

// Consolida o benchmark: tempo de fila, vazão, latência por lote, tokens reais, custo e acurácia.
const cfg = $('Configuração').first().json;
const rows = $input.all().map(i => i.json);
const LIMIAR = Number(cfg.limiar_alerta) || 0.7;

const APELIDOS = { 'claude-haiku-4-5-20251001': 'Claude Haiku 4.5', 'gpt-4.1-mini': 'GPT-4.1 mini' };
const MODELOS = [
  { key: 'jev', nome: 'Jev (TypeSafe)', sistema: 'Sistema 1', pin: cfg.preco_jev_entrada, pout: cfg.preco_jev_saida },
  { key: 'claude', nome: APELIDOS[cfg.modelo_claude] ?? cfg.modelo_claude, sistema: 'Sistema 2', pin: cfg.preco_claude_entrada, pout: cfg.preco_claude_saida },
  { key: 'gpt', nome: APELIDOS[cfg.modelo_gpt] ?? cfg.modelo_gpt, sistema: 'Sistema 2', pin: cfg.preco_gpt_entrada, pout: cfg.preco_gpt_saida }
];
const soma = a => a.reduce((x, y) => x + y, 0);
const pctl = (arr, p) => {
  if (!arr.length) return null;
  const s = [...arr].sort((x, y) => x - y);
  return s[Math.min(s.length - 1, Math.max(0, Math.ceil(p * s.length) - 1))];
};
const r2 = (v, d = 2) => (v == null || !Number.isFinite(v) ? null : Math.round(v * 10 ** d) / 10 ** d);

const stats = [];
for (const m of MODELOS) {
  const rs = rows.filter(r => r[m.key]);
  if (!rs.length) continue;
  const ok = rs.filter(r => r[m.key].ok);
  const t0 = Math.min(...rs.map(r => r[m.key].t0));
  const t1 = Math.max(...rs.map(r => r[m.key].t1));
  const lotes = {};
  for (const r of rs) {
    const x = r[m.key];
    lotes[x.t0] = Math.max(lotes[x.t0] ?? 0, x.t1 - x.t0);
  }
  const lat = Object.values(lotes);
  const tin = soma(ok.map(r => r[m.key].tokens_entrada || 0));
  const tout = soma(ok.map(r => r[m.key].tokens_saida || 0));
  const custo = tin / 1e6 * Number(m.pin || 0) + tout / 1e6 * Number(m.pout || 0);
  const porMil = ok.length ? custo / ok.length * 1000 : null;
  const acertoRota = ok.filter(r => r[m.key].rota === r.gabarito.rota).length;
  const acertoAlertas = ok.filter(r =>
    (r[m.key].risco_churn >= LIMIAR) === r.gabarito.evasao && (r[m.key].intencao_compra >= LIMIAR) === r.gabarito.compra
  ).length;
  const estimado = m.key === 'jev' && ok.some(r => r[m.key].tokens_estimados);
  const erros = rs.filter(r => !r[m.key].ok);
  const porTipo = {};
  for (const r of erros) porTipo[r[m.key].erro] = (porTipo[r[m.key].erro] ?? 0) + 1;
  stats.push({
    modelo: m.nome,
    sistema: m.sistema,
    registros: rs.length,
    respostas_validas: ok.length,
    erros: erros.length,
    tempo_fila_s: r2((t1 - t0) / 1000, 1),
    mensagens_por_s: r2(rs.length / Math.max(0.001, (t1 - t0) / 1000), 1),
    latencia_lote_p50_ms: pctl(lat, 0.5),
    latencia_lote_p95_ms: pctl(lat, 0.95),
    tokens_entrada: tin,
    tokens_saida: tout,
    custo_total_usd: r2(custo, 6),
    custo_por_mil_usd: r2(porMil, 4),
    projecao_100_mil_usd: r2(porMil == null ? null : porMil * 100, 2),
    acuracia_rota_pct: ok.length ? r2(acertoRota / ok.length * 100, 1) : null,
    acuracia_alertas_pct: ok.length ? r2(acertoAlertas / ok.length * 100, 1) : null,
    observacao: [
      estimado ? 'tokens do Jev estimados (API sem usage)' : null,
      ...Object.entries(porTipo).map(([tipo, qtd]) => `${qtd}× ${tipo}`)
    ].filter(Boolean).join(' · ') || null,
    _key: m.key
  });
}

const jev = stats.find(s => s._key === 'jev');
const comparacoes = stats.filter(s => s._key !== 'jev' && jev).map(s => {
  const both = rows.filter(r => r.jev?.ok && r[s._key]?.ok);
  const iguais = both.filter(r => r.jev.rota === r[s._key].rota).length;
  return {
    comparacao: `Jev × ${s.modelo}`,
    velocidade_x: jev.tempo_fila_s > 0 ? r2(s.tempo_fila_s / jev.tempo_fila_s, 1) : null,
    custo_x: jev.custo_por_mil_usd > 0 ? r2(s.custo_por_mil_usd / jev.custo_por_mil_usd, 1) : null,
    concordancia_rota_pct: both.length ? r2(iguais / both.length * 100, 1) : null
  };
});

return [{ json: {
  benchmark: {
    registros: rows.length,
    lote: Number(cfg.lote),
    semente: cfg.semente,
    executado_em: new Date().toISOString()
  },
  modelos: stats.map(({ _key, ...s }) => s),
  comparacoes
} }];

// Uma linha por modelo + uma linha por comparação: fica legível na visão de tabela do n8n.
const { modelos, comparacoes } = $json;
return [...modelos, ...comparacoes].map(json => ({ json }));

// Monta o painel em HTML (o nó "Painel do benchmark" renderiza este HTML na aba de saída).
const { benchmark, modelos, comparacoes } = $json;
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const n = (v, d = 1) => v == null ? '—' : Number(v).toLocaleString('pt-BR', { minimumFractionDigits: d, maximumFractionDigits: d });
const usd = v => v == null ? '—' : v < 0.01
  ? 'US$ ' + Number(v).toLocaleString('pt-BR', { maximumSignificantDigits: 2 })
  : 'US$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const PINK = '#e8006a', INK = '#0a0a0a', MUTED = '#5f5f6a', LINE = '#e2e2e8';

const barras = (titulo, campo, fmt, menorMelhor = true) => {
  const vals = modelos.map(m => m[campo]).filter(v => v != null);
  const max = Math.max(...vals, 1e-9);
  return `<div style="margin:22px 0 6px;font:700 12px 'JetBrains Mono',monospace;letter-spacing:.06em;text-transform:uppercase;color:${MUTED}">${esc(titulo)}${menorMelhor ? ' · menor é melhor' : ' · maior é melhor'}</div>`
    + modelos.map(m => {
      const v = m[campo];
      const w = v == null ? 0 : Math.max(1.5, v / max * 100);
      const cor = m.sistema === 'Sistema 1' ? PINK : INK;
      return `<div style="display:grid;grid-template-columns:200px 1fr 130px;gap:12px;align-items:center;margin:6px 0">
        <div style="font-weight:700">${esc(m.modelo)}<div style="font-weight:500;font-size:12px;color:${MUTED}">${esc(m.sistema)}</div></div>
        <div style="height:22px;background:#f0f0f3;border-radius:6px;overflow:hidden"><div style="height:100%;width:${w}%;background:${cor};border-radius:6px"></div></div>
        <div style="font-weight:900;font-size:18px;text-align:right;color:${cor}">${fmt(v)}</div>
      </div>`;
    }).join('');
};

const destaque = comparacoes.map(c =>
  `<div style="background:${PINK};color:#fff;border-radius:12px;padding:14px 18px;margin:8px 0;font-weight:800;font-size:19px">
    ${esc(c.comparacao)}: Jev ${c.velocidade_x != null ? n(c.velocidade_x) + '× mais rápido' : '—'}
    · ${c.custo_x != null ? n(c.custo_x) + '× mais barato' : '—'}
    <span style="font-weight:500;font-size:14px;opacity:.9"> · concordância de rota ${n(c.concordancia_rota_pct)}%</span>
  </div>`).join('');

const linhas = [
  ['Respostas válidas', m => `${m.respostas_validas}/${m.registros}`],
  ['Erros', m => String(m.erros)],
  ['Tempo de fila', m => n(m.tempo_fila_s) + ' s'],
  ['Mensagens/s', m => n(m.mensagens_por_s)],
  ['Latência por lote p50 / p95', m => `${m.latencia_lote_p50_ms ?? '—'} / ${m.latencia_lote_p95_ms ?? '—'} ms`],
  ['Tokens entrada / saída', m => `${(m.tokens_entrada || 0).toLocaleString('pt-BR')} / ${(m.tokens_saida || 0).toLocaleString('pt-BR')}`],
  ['Custo desta execução', m => usd(m.custo_total_usd)],
  ['Custo por 1.000', m => usd(m.custo_por_mil_usd)],
  ['Projeção 100 mil/mês', m => usd(m.projecao_100_mil_usd)],
  ['Acurácia da rota', m => n(m.acuracia_rota_pct) + '%'],
  ['Acurácia dos alertas', m => n(m.acuracia_alertas_pct) + '%']
];
const tabela = `<table style="width:100%;border-collapse:collapse;margin-top:26px;font-size:14px">
  <tr><th style="text-align:left;padding:8px;border-bottom:2px solid ${INK};font:700 11px 'JetBrains Mono',monospace;color:${MUTED};text-transform:uppercase">Métrica</th>
  ${modelos.map(m => `<th style="text-align:right;padding:8px;border-bottom:2px solid ${INK};color:${m.sistema === 'Sistema 1' ? PINK : INK}">${esc(m.modelo)}</th>`).join('')}</tr>
  ${linhas.map(([rot, f]) => `<tr><td style="padding:7px 8px;border-bottom:1px solid ${LINE}">${rot}</td>${modelos.map(m => `<td style="padding:7px 8px;border-bottom:1px solid ${LINE};text-align:right;font-weight:700">${esc(f(m))}</td>`).join('')}</tr>`).join('')}
</table>`;

const obs = modelos.filter(m => m.observacao).map(m => `<li>${esc(m.modelo)}: ${esc(m.observacao)}</li>`).join('');

const html = `<div style="font-family:Barlow,'Segoe UI',system-ui,sans-serif;color:${INK};background:#fff;padding:26px 28px;max-width:980px">
  <div style="font:700 12px 'JetBrains Mono',monospace;letter-spacing:.08em;text-transform:uppercase;color:${PINK}">Flowgrammers · Benchmark Sistema 1 × Sistema 2</div>
  <div style="font-weight:900;font-size:34px;line-height:1.05;margin:6px 0 4px">${benchmark.registros} mensagens · lote de ${benchmark.lote}</div>
  <div style="color:${MUTED};margin-bottom:14px">Mesmo dataset, mesmas perguntas, mesma concorrência. Custo = tokens devolvidos pela API × preços da Configuração.</div>
  ${destaque}
  ${barras('Tempo de fila (s)', 'tempo_fila_s', v => n(v) + ' s')}
  ${barras('Custo por 1.000 mensagens', 'custo_por_mil_usd', usd)}
  ${barras('Acurácia da rota (%)', 'acuracia_rota_pct', v => n(v) + '%', false)}
  ${tabela}
  ${obs ? `<ul style="color:${MUTED};font-size:13px;margin-top:14px">${obs}</ul>` : ''}
  <div style="color:${MUTED};font-size:12px;margin-top:16px">Gabarito sintético, semente ${esc(benchmark.semente)}. Tempos incluem a sua rede até cada API. Rode mais de uma vez antes de tirar conclusão.</div>
</div>`;
return [{ json: { html } }];
